<?php
namespace App\Http\Controllers\Admin\Academics;
use App\Models\Academics\Domain;use App\Models\Academics\DomainModule;use App\Models\Academics\Subject;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\View\View;
class DomainController extends BaseAcademicsController{public function index(Request $r):View{$subjects=Subject::orderBy('name')->get(['id','name']);$modules=DomainModule::orderBy('name')->get(['id','name']);$records=Domain::leftJoin('subjects','subjects.id','=','domain.subject_id')->select('domain.*','subjects.name as subject_name')->when($r->filled('search'),fn($q)=>$q->where('subjects.name','like','%'.$r->string('search').'%'))->orderBy('domain.id')->paginate(20)->withQueryString();$records->getCollection()->transform(function($x){$x->module_names=DB::table('domain_modules')->join('domainmodules','domainmodules.id','=','domain_modules.module_id')->where('domain_id',$x->id)->orderBy('domain_modules.id')->pluck('domainmodules.name')->all();return $x;});$domain=$r->integer('edit')?Domain::findOrFail($r->integer('edit')):null;$selectedModules=$domain?DB::table('domain_modules')->where('domain_id',$domain->id)->pluck('module_id')->map(fn($id)=>(int)$id)->all():[];return view('admin.academics.curriculum.domains',compact('subjects','modules','records','domain','selectedModules'));}private function rules(){return ['subject_id'=>'required|exists:subjects,id','modules'=>'required|array|min:1','modules.*'=>'integer|exists:domainmodules,id'];}private function syncModules($id,$ids){DB::table('domain_modules')->where('domain_id',$id)->delete();DB::table('domain_modules')->insert(array_map(fn($mid)=>['domain_id'=>$id,'module_id'=>$mid,'is_active'=>'yes'],$ids));}public function store(Request $r){$d=$r->validate($this->rules());DB::transaction(function()use($d){$s=Subject::findOrFail($d['subject_id']);$x=Domain::create(['subject_id'=>$s->id,'name'=>$s->name,'is_active'=>'yes']);$this->syncModules($x->id,$d['modules']);});return back()->with('success','Domain added successfully.');}public function update(Request $r,Domain $domain){$d=$r->validate($this->rules());DB::transaction(function()use($d,$domain){$s=Subject::findOrFail($d['subject_id']);$domain->update(['subject_id'=>$s->id,'name'=>$s->name]);$this->syncModules($domain->id,$d['modules']);});return back()->with('success','Domain updated successfully.');}public function destroy(Domain $domain){DB::transaction(function()use($domain){DB::table('domain_modules')->where('domain_id',$domain->id)->delete();$domain->delete();});return back()->with('success','Domain deleted successfully.');}}
